return $input.all();

// Get all topics from input
const allTopics = $input.first().json.output['all topics'];

// Get client ID from clients node (current iteration item)
const clientId = $('Pass the client through').item.json['Client ID'];

// Create output array
const outputItems = [];

// Loop through each topic and create separate items
for (let i = 0; i < allTopics.length; i++) {
  outputItems.push({
    json: {
      topic: allTopics[i],
      client_id: clientId
    }
  });
}

return outputItems;

const items = $input.all();
const lastItem = items[items.length - 1];
return [lastItem];
